ALTER TABLE "User" ADD COLUMN "disabledAt" TIMESTAMP(3);
ALTER TABLE "Department" ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "AcademicPeriod" ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "Announcement" ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "ClassGroup" ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "Conversation" ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "Module" ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "Lesson" ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "Exam" ADD COLUMN "published" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "archivedAt" TIMESTAMP(3), ADD COLUMN "maxAttempts" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "passingScore" DOUBLE PRECISION NOT NULL DEFAULT 7, ADD COLUMN "version" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Question" ADD COLUMN "archivedAt" TIMESTAMP(3);
CREATE TABLE "ExamAttempt" (
"id" TEXT NOT NULL PRIMARY KEY, "submissionId" TEXT NOT NULL, "examId" TEXT NOT NULL, "userId" TEXT NOT NULL, "number" INTEGER NOT NULL,
"score" DOUBLE PRECISION NOT NULL, "correct" INTEGER NOT NULL, "total" INTEGER NOT NULL, "passed" BOOLEAN NOT NULL,
"snapshot" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT "ExamAttempt_examId_fkey" FOREIGN KEY ("examId") REFERENCES "Exam"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
CONSTRAINT "ExamAttempt_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "ExamAttempt_examId_userId_number_key" ON "ExamAttempt"("examId", "userId", "number");
CREATE UNIQUE INDEX "ExamAttempt_userId_submissionId_key" ON "ExamAttempt"("userId", "submissionId");
CREATE INDEX "ExamAttempt_userId_createdAt_idx" ON "ExamAttempt"("userId", "createdAt");
